"""Project typed Rust carriage markers from the executable endpoint catalogue.

The projection carries no semantic validator registry. Rust's sealed
ValidatedOperation trait determines which markers are currently callable.
"""

from __future__ import annotations

import hashlib
import re
import subprocess


def render(raw: bytes, catalogue: dict) -> bytes:
    lines = [
        "// Generated by scripts/ci/check_generated_surfaces.py --write. Do not edit.",
        f"// Endpoint catalogue SHA-256: {hashlib.sha256(raw).hexdigest()}",
        "//! Typed metadata is not a promise of callable operation support.",
        "use crate::OperationMetadata;",
        "",
    ]
    seen_ids: set[str] = set()
    seen_symbols: set[str] = set()
    for endpoint in sorted(catalogue["endpoints"], key=lambda item: item["operation"]):
        operation = endpoint["operation"]
        if operation in seen_ids:
            raise ValueError(f"duplicate catalogue operation: {operation}")
        seen_ids.add(operation)
        if not (
            endpoint["authentication"] == "session_bearer"
            and endpoint["method"] == "post"
            and "{" not in endpoint["path"]
        ):
            continue
        if not re.fullmatch(r"[a-z][a-z0-9]*(?:-[a-z0-9]+)*", operation):
            raise ValueError(f"unsupported Rust operation name: {operation}")
        symbol = "".join(part[0].upper() + part[1:] for part in operation.split("-"))
        if symbol in seen_symbols:
            raise ValueError(f"colliding Rust operation symbol: {symbol}")
        seen_symbols.add(symbol)
        request, response = endpoint["request_type"], endpoint["response_type"]
        if any(not re.fullmatch(r"[A-Z][A-Za-z0-9]*", name) for name in (request, response)):
            raise ValueError(f"unsupported Rust wire type for {operation}")
        path = endpoint["path"]
        if not re.fullmatch(r"/v1/[a-z0-9/_-]+", path):
            raise ValueError(f"unsupported fixed Rust operation path: {path}")
        mutation = endpoint["mutation"]
        if type(mutation) is not bool:
            raise ValueError(f"mutation is not Boolean: {operation}")
        lines.extend([
            "#[derive(Debug, Clone, Copy)]",
            f"pub struct {symbol};",
            f"impl crate::catalogue_call::sealed::Sealed for {symbol} {{}}",
            f"impl OperationMetadata for {symbol} {{",
            f"    type Request = rrd_contract::{request};",
            f"    type Response = rrd_contract::{response};",
            f'    const OPERATION: &\'static str = "{operation}";',
            f'    const PATH: &\'static str = "{path}";',
            f"    const MUTATION: bool = {str(mutation).lower()};",
            "}",
            "",
        ])
    if not seen_symbols:
        raise ValueError("catalogue has no supported session POST metadata")
    formatted = subprocess.run(
        ["rustfmt", "--edition", "2021", "--emit", "stdout"],
        input="\n".join(lines).encode("utf-8"),
        capture_output=True,
        check=True,
    )
    return formatted.stdout.replace(b"\r\n", b"\n")
